"""Validation and rendering of AI-proposed edits. The model's edits are untrusted data:

* each edit must quote the *exact* current source text it replaces (rejects invented code),
* edits may only touch lines inside the verified mapping window (no unrelated changes),
* the result must parse as Python and may not introduce dangerous constructs or new imports,
* the diff is generated by ASE with difflib - the model never supplies a diff or a file path.
Nothing here writes to disk; applying a patch is a separate, later, human-approved phase.
"""
from __future__ import annotations

import ast
import difflib
import re
from dataclasses import dataclass
from hashlib import sha256

from app.ai.schemas import ModelEdit, ModelPatch
from app.remediation.source import SourceContext

MAX_EDIT_LINES = 40
MAX_ADDED_LINES = 60
MAX_REPLACEMENT_CHARS = 6000

_DANGEROUS = re.compile(
    r"\b(os\.system|os\.popen|subprocess|eval\s*\(|exec\s*\(|compile\s*\(|__import__|importlib|socket|"
    r"ctypes|pickle|marshal|shutil|open\s*\(|urllib\.request|requests|httpx)\b")
_IMPORT = re.compile(r"^\s*(import|from)\s+\S+")
_CONTROL = re.compile(r"[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]")
# Imports a remediation may legitimately add, matched against the module (first dotted segment).
_ALLOWED_IMPORT_MODULES = {"html", "re", "urllib"}
_REPOSITORY_IMPORT_MODULES = _ALLOWED_IMPORT_MODULES | {"ast", "json", "secrets", "hashlib"}


class PatchRejected(Exception):
    def __init__(self, code: str, message: str):
        super().__init__(message)
        self.code = code
        self.message = message


@dataclass(frozen=True)
class ValidatedPatch:
    unified_diff: str
    patch_sha256: str
    patched_sha256: str
    edits: list[dict]
    checks: dict


def _norm(text: str) -> list[str]:
    return text.replace("\r\n", "\n").replace("\r", "\n").split("\n")


def validate_and_render(source: SourceContext, patch: ModelPatch) -> ValidatedPatch:
    edits: list[ModelEdit] = sorted(patch.edits, key=lambda e: e.start_line)
    previous_end = 0
    for edit in edits:
        if edit.end_line < edit.start_line:
            raise PatchRejected("PATCH_INVALID_RANGE", "An edit ends before it starts.")
        if edit.start_line < source.start_line or edit.end_line > source.end_line:
            raise PatchRejected("PATCH_OUTSIDE_WINDOW",
                                f"Edits may only change lines {source.start_line}-{source.end_line} (verified mapping window).")
        if edit.start_line <= previous_end:
            raise PatchRejected("PATCH_OVERLAP", "Edits overlap.")
        if edit.end_line - edit.start_line + 1 > MAX_EDIT_LINES:
            raise PatchRejected("PATCH_TOO_LARGE", "An edit spans too many lines.")
        if len(edit.replacement_text) > MAX_REPLACEMENT_CHARS or _CONTROL.search(edit.replacement_text) \
                or _CONTROL.search(edit.original_text):
            raise PatchRejected("PATCH_INVALID_CONTENT", "Edit content is oversized or contains control characters.")
        actual = source.lines[edit.start_line - 1:edit.end_line]
        if _norm(edit.original_text) != list(actual):
            raise PatchRejected("PATCH_ORIGINAL_MISMATCH",
                                "The quoted original text does not match the current source; the patch was not applied.")
        previous_end = edit.end_line

    new_lines = list(source.lines)
    added_total = 0
    for edit in reversed(edits):  # bottom-up keeps earlier line numbers valid
        replacement = _norm(edit.replacement_text)
        if replacement == [""]:
            replacement = []
        added_total += len(replacement)
        from app.remediation.process_policy import safe_process_edit
        safe_process = source.kind == "MANAGED_REPOSITORY" and safe_process_edit(edit.replacement_text)
        for line in replacement:
            checked_line = line.replace("subprocess.run", "safe_process_run") if safe_process else line
            if _DANGEROUS.search(checked_line):
                raise PatchRejected("PATCH_DANGEROUS_CONSTRUCT", "The patch introduces a disallowed construct.")
            if _IMPORT.match(line):
                module = line.split()[1].split(".")[0]
                if module not in (_REPOSITORY_IMPORT_MODULES if source.kind == "MANAGED_REPOSITORY" else _ALLOWED_IMPORT_MODULES):
                    raise PatchRejected("PATCH_NEW_IMPORT", f"The patch imports '{module}', which is not on the allow-list.")
        new_lines[edit.start_line - 1:edit.end_line] = replacement
    if added_total > MAX_ADDED_LINES:
        raise PatchRejected("PATCH_TOO_LARGE", "The patch adds too many lines.")

    if new_lines == list(source.lines):
        raise PatchRejected("PATCH_NO_CHANGE", "The proposed patch does not change the source.")
    patched = "\n".join(new_lines) + "\n"
    from app.remediation.languages import syntax_check
    syntax = syntax_check(source.path, patched)
    if syntax["status"] != "PASS":
        raise PatchRejected("PATCH_SYNTAX_ERROR" if syntax["status"] == "FAIL" else "UNSUPPORTED_LANGUAGE", syntax["detail"])

    diff = "".join(difflib.unified_diff(
        [line + "\n" for line in source.lines], [line + "\n" for line in new_lines],
        fromfile=f"a/{source.path}", tofile=f"b/{source.path}", n=3))
    added = sum(1 for l in diff.splitlines() if l.startswith("+") and not l.startswith("+++"))
    removed = sum(1 for l in diff.splitlines() if l.startswith("-") and not l.startswith("---"))
    checks = {
        "evidence_note": "Measured by ASE on the proposal only. This is NOT verification: no tests or rescans have run.",
        "applies_cleanly": {"status": "PASS", "detail": "Quoted original text matched current source exactly."},
        "within_mapped_window": {"status": "PASS", "detail": f"All edits inside lines {source.start_line}-{source.end_line}."},
        "syntax_valid": syntax,
        "python_syntax_valid": syntax if syntax["language"] == "Python" else {"status": "NOT_APPLICABLE"},
        "files_changed": {"status": "PASS", "value": 1, "detail": source.path},
        "dangerous_constructs_absent": {"status": "PASS", "detail": "No disallowed calls or imports in added lines."},
        "lines_added": added, "lines_removed": removed,
        "functional_tests": {"status": "NOT_RUN"},
        "static_security_reanalysis": {"status": "NOT_RUN"},
        "dynamic_rescan": {"status": "NOT_RUN"},
        "original_vulnerability_reproduced_after_patch": {"status": "NOT_RUN"},
    }
    return ValidatedPatch(
        unified_diff=diff, patch_sha256=sha256(diff.encode()).hexdigest(),
        patched_sha256=sha256(patched.encode()).hexdigest(),
        edits=[e.model_dump() for e in edits], checks=checks)
